import fse from 'fs-extra';
import os from 'os';
import path from 'path';
import { generatePages, withIndexRouteAliases, writeStaticUserInfo, } from '../local-preview/export.js';
import { getGroupFilteredRoutes } from '../local-preview/getGroupFilteredRoutes.js';
describe('getGroupFilteredRoutes', () => {
    it('prunes routes outside the selected groups', () => {
        const routes = getGroupFilteredRoutes({
            groups: [
                {
                    group: 'Guides',
                    pages: [
                        { href: '/index', title: 'Introduction' },
                        { href: '/quickstart', title: 'Quickstart', groups: ['admin'] },
                        { href: '/development', title: 'Development', groups: ['developer'] },
                        { href: '/authenticated', title: 'Authenticated', groups: ['*'] },
                    ],
                },
            ],
        }, ['admin']);
        expect(routes).toEqual(['/', '/index', '/quickstart', '/authenticated']);
    });
});
describe('withIndexRouteAliases', () => {
    it('adds the parent route for nested index pages', () => {
        expect(withIndexRouteAliases(['/', '/index', '/agent/index', '/agent/slack'])).toEqual([
            '/',
            '/index',
            '/agent/index',
            '/agent',
            '/agent/slack',
        ]);
    });
    it('does not duplicate routes that are already listed', () => {
        expect(withIndexRouteAliases(['/cli', '/cli/index'])).toEqual(['/cli', '/cli/index']);
    });
});
describe('generatePages', () => {
    let outputDir;
    beforeEach(async () => {
        outputDir = await fse.mkdtemp(path.join(os.tmpdir(), 'mint-export-test-'));
    });
    afterEach(async () => {
        vi.unstubAllGlobals();
        await fse.remove(outputDir);
    });
    const pageFetch = () => vi.fn(async (_input, init) => new Headers(init?.headers).get('RSC') === '1'
        ? new Response('0:{"b":"build"}\n', { headers: { 'content-type': 'text/x-component' } })
        : new Response('<html>Introduction</html>', { headers: { 'content-type': 'text/html' } }));
    it('uses the first accessible route for the root page', async () => {
        const fetchMock = pageFetch();
        vi.stubGlobal('fetch', fetchMock);
        const failedPageCount = await generatePages('http://localhost:3000', ['/'], outputDir, '/introduction');
        expect(failedPageCount).toBe(0);
        expect(fetchMock).toHaveBeenCalledWith('http://localhost:3000/introduction');
        await expect(fse.readFile(path.join(outputDir, 'index.html'), 'utf8')).resolves.toBe('<html>Introduction</html>');
    });
    it('saves the rsc payload next to each page for soft navigation', async () => {
        const fetchMock = pageFetch();
        vi.stubGlobal('fetch', fetchMock);
        const failedPageCount = await generatePages('http://localhost:3000', ['/', '/guides/math'], outputDir);
        expect(failedPageCount).toBe(0);
        expect(fetchMock).toHaveBeenCalledWith('http://localhost:3000/guides/math', {
            headers: { RSC: '1' },
        });
        await expect(fse.readFile(path.join(outputDir, 'index.txt'), 'utf8')).resolves.toBe('0:{"b":"build"}\n');
        await expect(fse.readFile(path.join(outputDir, 'guides', 'math', 'index.txt'), 'utf8')).resolves.toBe('0:{"b":"build"}\n');
    });
    it('fails the page when the rsc request does not return a payload', async () => {
        vi.stubGlobal('fetch', vi.fn(async () => new Response('<html></html>', { headers: { 'content-type': 'text/html' } })));
        await expect(generatePages('http://localhost:3000', ['/quickstart'], outputDir)).resolves.toBe(1);
    });
});
describe('writeStaticUserInfo', () => {
    let outputDir;
    beforeEach(async () => {
        outputDir = await fse.mkdtemp(path.join(os.tmpdir(), 'mint-export-test-'));
    });
    afterEach(async () => {
        await fse.remove(outputDir);
    });
    it('writes mock groups to the static user endpoint', async () => {
        await writeStaticUserInfo(outputDir, ['admin', 'user']);
        const userInfo = await fse.readJson(path.join(outputDir, '_mintlify', 'api', 'user', 'index.html'));
        expect(userInfo).toEqual({ user: { groups: ['admin', 'user'] } });
    });
    it('does not write the endpoint without groups', async () => {
        await writeStaticUserInfo(outputDir, undefined);
        const endpointExists = await fse.pathExists(path.join(outputDir, '_mintlify', 'api', 'user', 'index.html'));
        expect(endpointExists).toBe(false);
    });
});
